//! `Debug` redaction generated by `#[settings(fragment = true)]` for
//! `#[setting(secret)]` fields.

use reinhardt_core::macros::settings;
use rstest::rstest;
use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// Fixture fragments
// ---------------------------------------------------------------------------

/// Explicit `derive(Debug)` together with secret fields.
#[settings(fragment = true, section = "derived_secrets")]
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
struct DerivedSecretSettings {
	host: String,
	#[setting(secret)]
	api_key: String,
	#[setting(secret)]
	password: Option<String>,
	#[cfg(any())]
	disabled: String,
}

/// No `derive` attribute: the macro supplies the derives itself.
#[settings(fragment = true, section = "implicit_secrets")]
struct ImplicitSecretSettings {
	#[setting(secret)]
	token: String,
}

/// Qualified `Debug` path in the derive list.
#[settings(fragment = true, section = "qualified_secrets")]
#[derive(Clone, std::fmt::Debug, Serialize, Deserialize)]
struct QualifiedSecretSettings {
	#[setting(secret)]
	token: String,
}

/// No secret fields: the user's `derive(Debug)` is kept as written.
#[settings(fragment = true, section = "plain")]
#[derive(Clone, Debug, Serialize, Deserialize)]
struct PlainSettings {
	token: String,
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[rstest]
fn derived_debug_redacts_secret_fields() {
	// Arrange
	let settings = DerivedSecretSettings {
		host: "db.internal".to_string(),
		api_key: "api-key-value".to_string(),
		password: Some("password-value".to_string()),
	};

	// Act
	let output = format!("{settings:?}");

	// Assert
	assert_eq!(
		output,
		r#"DerivedSecretSettings { host: "db.internal", api_key: "[REDACTED]", password: Some("[REDACTED]") }"#
	);
}

#[rstest]
fn derived_debug_shows_absent_optional_secret_as_none() {
	// Arrange
	let settings = DerivedSecretSettings::default();

	// Act
	let output = format!("{settings:?}");

	// Assert
	assert_eq!(
		output,
		r#"DerivedSecretSettings { host: "", api_key: "[REDACTED]", password: None }"#
	);
}

#[rstest]
fn implicit_derives_redact_secret_fields() {
	// Arrange
	let settings: ImplicitSecretSettings =
		serde_json::from_str(r#"{"token":"implicit-token-value"}"#).unwrap();

	// Act
	let output = format!("{:?}", settings.clone());

	// Assert
	assert_eq!(output, r#"ImplicitSecretSettings { token: "[REDACTED]" }"#);
	assert_eq!(settings.token, "implicit-token-value");
}

#[rstest]
fn qualified_debug_derive_redacts_secret_fields() {
	// Arrange
	let settings = QualifiedSecretSettings {
		token: "qualified-token-value".to_string(),
	};

	// Act
	let output = format!("{settings:?}");

	// Assert
	assert_eq!(output, r#"QualifiedSecretSettings { token: "[REDACTED]" }"#);
}

#[rstest]
fn non_secret_fields_keep_derived_debug() {
	// Arrange
	let settings = PlainSettings {
		token: "visible-value".to_string(),
	};

	// Act
	let output = format!("{settings:?}");

	// Assert
	assert_eq!(output, r#"PlainSettings { token: "visible-value" }"#);
}
